-- exmd2-4.hs: extended Minsky doubling (value x2, 4 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 2^4 = 16.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x2
exmd (x, 0,    2) = exmd (  x,   0,    5)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=5): x -> y, x2
exmd (0, y,    5) = exmd (  0,   y,    8)
exmd (x, y,    5) = exmd (x-1,   y,    6)
exmd (x, y,    6) = exmd (  x, y+1,    7)
exmd (x, y,    7) = exmd (  x, y+1,    5)

-- Cycle 2 (pc=8): y -> x, x2
exmd (x, 0,    8) = exmd (  x,   0,   11)
exmd (x, y,    8) = exmd (  x, y-1,    9)
exmd (x, y,    9) = exmd (x+1,   y,   10)
exmd (x, y,   10) = exmd (x+1,   y,    8)

-- Cycle 3 (pc=11): x -> y, x2
exmd (0, y,   11) = exmd (  0,   y,   14)
exmd (x, y,   11) = exmd (x-1,   y,   12)
exmd (x, y,   12) = exmd (  x, y+1,   13)
exmd (x, y,   13) = exmd (  x, y+1,   11)

-- Drain (pc=14): DEC y to 0, then HALT
exmd (x, 0,   14) = (  x,   0,    1)
exmd (x, y,   14) = exmd (  x, y-1,   14)
